function subcategoryOptions(category){const found=Object.entries(subcategoryMap).find(([k])=>tr(k)===category||k===category);const arr=found?.[1]||['सामान्य खर्च','मरम्मत','अन्य'];return [{value:'',label:'चुनें (वैकल्पिक)'},...arr.map(x=>({value:x,label:x}))]}
const APP_URL='https://fabrication4man-bot.github.io/GharKhata/';
function groceryDefaultRows(){return Array.from({length:50},(_,i)=>({no:i+1,item:'',qty:'',unit:'PCS',price:''}))}
function groceryMonth(){return $('#groceryMonth')?.value||currentMonth()}
function renderGrocery(){const monthEl=$('#groceryMonth');if(!monthEl)return;if(!monthEl.value)monthEl.value=currentMonth();let rows=window.groceryRows||groceryDefaultRows();const en=state.lang==='en';const units=[['Gram',en?'Gram':'ग्राम'],['Kilogram',en?'Kilogram':'किलोग्राम'],['Liter',en?'Liter':'लीटर'],['Milliliter',en?'Milliliter':'मिलीलीटर'],['PCS',en?'Pieces':'पीस'],['रुपये के हिसाब से',en?'By amount':'रुपये के हिसाब से']];$('#groceryRows').innerHTML=rows.map((r,i)=>`<tr><td>${i+1}</td><td><input data-grocery="item" data-i="${i}" value="${escapeHtml(r.item||'')}" aria-label="${en?'Item':'सामान'} ${i+1}" placeholder="${en?'Item name':'सामान का नाम'}"></td><td><input data-grocery="qty" data-i="${i}" type="number" min="0" step="any" value="${escapeHtml(r.qty||'')}" aria-label="${en?'Quantity':'मात्रा'}"></td><td><select data-grocery="unit" data-i="${i}">${units.map(([v,label])=>`<option value="${v}" ${v===(r.unit||'PCS')?'selected':''}>${label}</option>`).join('')}</select></td><td><input data-grocery="price" data-i="${i}" type="number" min="0" step="0.01" value="${escapeHtml(r.price||'')}" placeholder="${en?'Optional':'वैकल्पिक'}" aria-label="${en?'Price':'कीमत'}"></td></tr>`).join('');const add=$('#addGroceryRow');if(add)add.textContent=en?'＋ Add row':'＋ नई लाइन जोड़ें';const save=$('#saveGrocery');if(save)save.textContent=en?'Save list':'लिस्ट सेव करें'}
function readGroceryRows(){return [...document.querySelectorAll('#groceryRows tr')].map((tr,i)=>({no:i+1,item:tr.querySelector('[data-grocery=item]').value.trim(),qty:tr.querySelector('[data-grocery=qty]').value,unit:tr.querySelector('[data-grocery=unit]').value,price:tr.querySelector('[data-grocery=price]').value}));}
async function saveGrocery(showToast=true){const month=groceryMonth(),rows=readGroceryRows();await put('groceryLists',{id:month,month,rows,updatedAt:new Date().toISOString()});window.groceryRows=rows;if(showToast)toast(state.lang==='en'?'Monthly grocery list saved':'मासिक किराना लिस्ट सेव हो गई')}
let grocerySaveTimer;function scheduleGrocerySave(){clearTimeout(grocerySaveTimer);grocerySaveTimer=setTimeout(()=>saveGrocery(false).catch(()=>{}),600)}
function addGroceryRow(){const rows=readGroceryRows();rows.push({no:rows.length+1,item:'',qty:'',unit:'PCS',price:''});window.groceryRows=rows;renderGrocery();scheduleGrocerySave()}
async function loadGrocery(silent=false){const month=groceryMonth(),saved=(await all('groceryLists')).find(x=>x.month===month);window.groceryRows=saved?.rows||groceryDefaultRows();renderGrocery();if(!silent)toast(saved?'सेव की गई लिस्ट खुल गई':'नई मासिक लिस्ट तैयार है')}
function groceryCsv(){const rows=readGroceryRows().filter(r=>r.item||r.qty||r.price);const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';return ['S.No,Item,Quantity,Unit,Price',...rows.map(r=>[r.no,r.item,r.qty,r.unit,r.price].map(q).join(','))].join('\r\n')}
async function shareText(title,textValue){if(navigator.share){try{await navigator.share({title,text:textValue,url:APP_URL});return}catch(e){if(e.name==='AbortError')return}}download((title||'gharkhata')+'.txt',textValue,'text/plain;charset=utf-8')}
async function shareGrocery(){const rows=readGroceryRows().filter(r=>r.item||r.qty||r.price);const textValue='GharKhata मासिक किराना सूची — '+groceryMonth()+'\n'+rows.map(r=>`${r.no}. ${r.item||'—'} | ${r.qty||'—'} ${r.unit} | ${r.price?'कीमत: '+r.price:'कीमत खाली'}`).join('\n');await shareText('GharKhata-Kirana-'+groceryMonth(),textValue)}
function printCurrent(id,title){if(id==='#groceryRows'){const rows=readGroceryRows().filter(r=>r.item||r.qty||r.price);const en=state.lang==='en';const table='<table><thead><tr><th>No.</th><th>'+(en?'Item':'सामान')+'</th><th>'+(en?'Quantity':'मात्रा')+'</th><th>'+(en?'Unit':'यूनिट')+'</th><th>'+(en?'Price':'कीमत')+'</th></tr></thead><tbody>'+rows.map((r,i)=>'<tr><td>'+(i+1)+'</td><td>'+escapeHtml(r.item)+'</td><td>'+escapeHtml(r.qty)+'</td><td>'+escapeHtml(r.unit)+'</td><td>'+escapeHtml(r.price)+'</td></tr>').join('')+'</tbody></table>';const w=window.open('','_blank');if(!w){toast(en?'Allow pop-ups to print':'प्रिंट के लिए पॉप-अप अनुमति दें');return}w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>'+escapeHtml(title)+'</title><style>@page{margin:12mm}body{font-family:Arial,sans-serif;color:#17231f;font-size:12px}h1{font-size:20px;margin:0 0 4px}p{margin:0 0 14px;color:#566}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #cbd5d1;padding:5px 7px;text-align:left;overflow-wrap:anywhere}th:first-child,td:first-child{width:8%}th:nth-child(2),td:nth-child(2){width:42%}th:nth-child(3),td:nth-child(3){width:16%}th:nth-child(4),td:nth-child(4){width:16%}th:nth-child(5),td:nth-child(5){width:18%}th{background:#eaf2ee}footer{margin-top:22px;border-top:1px solid #ccc;padding-top:8px;font-size:10px}</style></head><body><h1>GharKhata</h1><p>'+escapeHtml(title)+' · '+escapeHtml(groceryMonth())+'</p>'+table+'<footer>GharKhata — '+(en?'Your family finances, in one place':'घर का हर खर्च, एक जगह')+' · '+escapeHtml(APP_URL)+'</footer><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>');w.document.close();return}const el=$(id);if(!el)return;const w=window.open('','_blank');if(!w){toast('ब्राउज़र में pop-up अनुमति दें');return}w.document.write('<html><head><meta charset="utf-8"><title>'+escapeHtml(title)+'</title><style>body{font-family:Arial,sans-serif;padding:20px;color:#17231f}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccc;padding:7px;text-align:left}button,input,select{display:none}@media print{body{padding:0}}</style></head><body><h1>'+escapeHtml(title)+'</h1>'+el.innerHTML+'</body></html>');w.document.close();w.focus();setTimeout(()=>w.print(),300)}
async function downloadReport(){const month=$('#reportMonth').value||currentMonth();const txs=(window.transactions||[]).filter(t=>monthOf(t.date)===month);const inc=sum(txs,t=>t.type==='income'),exp=sum(txs,t=>t.type==='expense');const txt=`GharKhata — मासिक रिपोर्ट\nमहीना: ${month}\nकुल आय: ${fmt(inc)}\nकुल खर्च: ${fmt(exp)}\nबचत / अंतर: ${fmt(inc-exp)}\n\nखर्च का विवरण:\n`+txs.filter(t=>t.type==='expense').map(t=>`${t.date} | ${t.category} | ${t.subcategory||''} | ${t.title||''} | ${fmt(t.amount,t.currency||'INR')}`).join('\n');download(`GharKhata-report-${month}.txt`,txt,'text/plain;charset=utf-8')}
async function shareReport(){const month=$('#reportMonth').value||currentMonth();const txs=(window.transactions||[]).filter(t=>monthOf(t.date)===month);const inc=sum(txs,t=>t.type==='income'),exp=sum(txs,t=>t.type==='expense');await shareText('GharKhata मासिक रिपोर्ट',`महीना: ${month}\nकुल आय: ${fmt(inc)}\nकुल खर्च: ${fmt(exp)}\nबचत / अंतर: ${fmt(inc-exp)}\nरिपोर्ट ऐप में उपलब्ध है।`)}
async function renderOrders(){if(!$('#orderList'))return;const rows=(await all('orders')).sort((a,b)=>(b.orderDate||'').localeCompare(a.orderDate||''));$('#orderList').innerHTML=rows.length?rows.map(o=>`<div class="record"><div class="record-icon">📦</div><div class="record-main"><b>${escapeHtml(o.item)} — ${escapeHtml(o.platform)}</b><small>${escapeHtml(o.orderDate||'')} · ${escapeHtml(o.status||'')} · ID: ${escapeHtml(o.orderId||'—')}<br>मात्रा: ${escapeHtml(o.quantity||1)} · सामान ₹${Number(o.price||0).toFixed(2)} + डिलीवरी ₹${Number(o.shipping||0).toFixed(2)} − डिस्काउंट ₹${Number(o.discount||0).toFixed(2)} · रिफंड ₹${Number(o.refund||0).toFixed(2)}</small><div class="record-actions"><button class="mini-btn" data-order-delete="${o.id}">हटाएँ</button></div></div><div class="record-amount">₹${(Number(o.price||0)+Number(o.shipping||0)-Number(o.discount||0)-Number(o.refund||0)).toFixed(2)}</div></div>`).join(''):emptyHTML('अभी कोई ऑनलाइन ऑर्डर दर्ज नहीं है।')}
async function saveOrder(e){e.preventDefault();const f=new FormData(e.target),o=Object.fromEntries(f.entries());o.id=uid();['quantity','price','shipping','discount','refund'].forEach(k=>o[k]=Number(o[k])||0);o.total=Math.max(0,o.price+o.shipping-o.discount);o.createdAt=new Date().toISOString();if(o.status!=='कैंसिल'&&o.total>0){const account=(window.accounts||[])[0];if(account){const net=Math.max(0,o.total-o.refund);const tx={id:uid(),date:o.orderDate||today(),amount:net,currency:account.currency||'INR',type:'expense',category:tr('ecommerce'),subcategory:o.category||'ऑनलाइन खरीदारी',account:account.id,member:'',method:o.payment||'',person:o.platform||'',title:o.item,notes:`Order ID: ${o.orderId||'—'}; status: ${o.status}; invoice: ${o.invoice||''}; ${o.notes||''}`,reason:o.notes||'',orderId:o.orderId||'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),ecommerce:true};await put('transactions',tx);o.transactionId=tx.id;}}await put('orders',o);e.target.reset();e.target.elements.orderDate.value=today();await renderAll();toast('ऑर्डर का विवरण सेव हो गया और खर्च रिपोर्ट में जोड़ा गया')}
async function exportOrders(){const rows=await all('orders'),heads=['platform','orderId','item','category','quantity','price','shipping','discount','total','orderDate','deliveryDate','payment','status','refund','invoice','notes'];const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';download('GharKhata-ecommerce-orders.csv','\ufeff'+[heads.join(','),...rows.map(o=>heads.map(k=>q(o[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8')}
async function shareApp(){await shareText('GharKhata — घर का हर खर्च, एक जगह','GharKhata ऐप खोलें: '+APP_URL+'\nपरिवार के खर्च, किराना सूची, ऑनलाइन ऑर्डर और महीने की बचत का हिसाब एक जगह।')}
function initSharePage(){const of=$('#orderForm');if(of&&!of.elements.orderDate.value)of.elements.orderDate.value=today()}

function addListeners(){document.addEventListener('click',async e=>{const pg=e.target.closest('[data-page]');if(pg){go(pg.dataset.page);return}const close=e.target.closest('[data-close-modal]');if(close){closeModal();return}const quick=e.target.closest('[data-type]');if(quick){openModal('transaction',null,{type:quick.dataset.type});return}const edit=e.target.closest('[data-edit]');if(edit){await editFromStore(edit.dataset.store,edit.dataset.edit);return}const delBtn=e.target.closest('[data-delete]');if(delBtn){await removeRecord(delBtn.dataset.store,delBtn.dataset.delete);return}const od=e.target.closest('[data-order-delete]');if(od){if(confirm('इस ऑर्डर को हटाएँ?')){const order=(await all('orders')).find(x=>x.id===od.dataset.orderDelete);await del('orders',od.dataset.orderDelete);if(order?.transactionId)await del('transactions',order.transactionId);await renderAll()}return}});$('#langToggle').onclick=()=>setLang(state.lang==='en'?'hi':'en');$('#settingsLang').onclick=()=>setLang(state.lang==='en'?'hi':'en');$('#quickAdd').onclick=()=>openModal('transaction');$('#newTransaction').onclick=()=>openModal('transaction');$('#newFarm').onclick=()=>openModal('farmTransaction',null,{type:'expense'});$('#newAccount').onclick=()=>openModal('account');$('#newMember').onclick=()=>openModal('member');$('#newBudget').onclick=()=>openModal('budget');$('#newReminder').onclick=()=>openModal('reminder');$('#newCategory').onclick=()=>openModal('category');$('#searchTransactions').oninput=renderTransactions;$('#filterType').onchange=renderTransactions;$('#reportMonth').onchange=renderReports;$('#exportCsv').onclick=exportCsv;$('#downloadReport').onclick=downloadReport;$('#printReport').onclick=()=>printCurrent('#reports','GharKhata मासिक रिपोर्ट');$('#shareReport').onclick=shareReport;$('#groceryMonth').onchange=()=>loadGrocery(true);$('#loadGrocery').onclick=()=>loadGrocery(false);if($('#addGroceryRow'))$('#addGroceryRow').onclick=addGroceryRow;$('#groceryRows').addEventListener('input',e=>{if(e.target.matches('[data-grocery]')){window.groceryRows=readGroceryRows();scheduleGrocerySave()}});$('#groceryRows').addEventListener('change',e=>{if(e.target.matches('[data-grocery]')){window.groceryRows=readGroceryRows();scheduleGrocerySave()}});$('#saveGrocery').onclick=saveGrocery;$('#downloadGrocery').onclick=()=>download('GharKhata-kirana-'+groceryMonth()+'.csv','\ufeff'+groceryCsv(),'text/csv;charset=utf-8');$('#printGrocery').onclick=()=>printCurrent('#groceryRows','GharKhata मासिक किराना सूची '+groceryMonth());$('#shareGrocery').onclick=shareGrocery;$('#orderForm').onsubmit=saveOrder;$('#exportOrders').onclick=exportOrders;$('#shareAppLink').onclick=shareApp;$('#copyAppLink').onclick=async()=>{try{await navigator.clipboard.writeText(APP_URL);toast('ऐप लिंक कॉपी हो गया')}catch{await shareApp()}};$('#createBackup').onclick=backup;$('#restoreFile').onchange=e=>{if(e.target.files[0])restore(e.target.files[0]);e.target.value=''};$('#backupReminderToggle').onchange=e=>{state.backupReminder=e.target.checked;localStorage.setItem('hem_backup_reminder',String(state.backupReminder));toast(tr('saved'))};$('#clearData').onclick=async()=>{if(!confirm(tr('confirmClear')))return;for(const s of ['transactions','accounts','members','budgets','reminders','categories','farm','groceryLists','orders'])await clearStore(s);await seed();await renderAll();toast(tr('deleted'))};$$('.nav-item').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));initSharePage();if($('#orderForm'))$('#orderForm').elements.orderDate.value=today();}
async function init(){try{db=await openDB();await seed();window.groceryRows=groceryDefaultRows();addListeners();setLang(state.lang);await loadGrocery(true);if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});if(!window.isSecureContext&&location.protocol!=='file:')toast('For offline install, open this app over HTTPS.')}catch(e){document.body.innerHTML='<main><h2>Storage unavailable</h2><p>This browser could not open local storage. Try opening the app in Chrome.</p></main>';console.error(e)}}
init();
